/* prog27_soundex – reconstructed from the obfuscated binary.
 *
 * Behaviour:
 *   • If no argument is supplied, or the supplied argument is an empty
 *     string, the program prints the literal line:
 *           EMPTY
 *   • Otherwise it prints the Soundex code of the first argument.
 *
 * The Soundex algorithm used matches the classic definition:
 *   – The first character (converted to upper‑case) is kept unchanged.
 *   – Remaining letters are mapped to digits:
 *        B, F, P, V           → 1
 *        C, G, J, K, Q, S, X, Z → 2
 *        D, T                 → 3
 *        L                    → 4
 *        M, N                 → 5
 *        R                    → 6
 *        All other characters (including A, E, I, O, U, H, W, Y
 *        and any non‑alphabetic character) → 0 (ignored)
 *   – Consecutive duplicate digits are suppressed.
 *   – Digits ‘0’ are never emitted; they are only used for padding.
 *   – The result is padded with ‘0’ to a total length of 4 characters
 *     (first letter + three digits) and terminated with a NUL.
 *
 * This clear implementation reproduces the exact observable output of
 * the original binary while being easy to read and maintain.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* Return the Soundex digit for an upper‑case alphabetic character.
 * Mapping (standard Soundex):
 *   B, F, P, V           → 1
 *   C, G, J, K, Q, S, X, Z → 2
 *   D, T                 → 3
 *   L                    → 4
 *   M, N                 → 5
 *   R                    → 6
 *   All other characters → 0
 */
static int soundex_digit(char c)
{
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

/* Compute the Soundex code for the supplied string.
 * The result is stored in the supplied buffer, which must be at
 * least 5 bytes long (4 characters plus a terminating NUL).
 */
static void compute_soundex(const char *src, char *dst)
{
    /* First character – upper‑cased and stored directly */
    dst[0] = (char)toupper((unsigned char)src[0]);

    int prev_digit = soundex_digit(dst[0]);   /* digit of the first letter */
    int out_idx   = 1;                        /* next position in dst */
    size_t i = 1;

    while (src[i] != '\0' && out_idx < 4) {
        char ch = (char)toupper((unsigned char)src[i]);
        int digit = soundex_digit(ch);

        if (digit != 0 && digit != prev_digit) {
            dst[out_idx++] = (char)('0' + digit);
            prev_digit = digit;
        } else if (digit != 0) {
            /* duplicate digit – update prev_digit but do not output */
            prev_digit = digit;
        }
        /* letters that map to 0 are ignored */
        ++i;
    }

    /* Pad with '0' if fewer than three digits were produced */
    while (out_idx < 4) {
        dst[out_idx++] = '0';
    }
    dst[4] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char result[5];
    compute_soundex(argv[1], result);
    puts(result);
    return 0;
}
